docs/specs/schemas/rulith-agent-mcp-meta.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-agent-mcp-meta-v1.schema.json",
  "title": "Rulith Host-only MCP metadata (rulith/v1)",
  "description": "Gateway output only. This value never enters the model tool schema or transcript. Session identity comes only from the authenticated Mcp-Session-Id header. Namespace and tool names are projections of protocol/mcp-surface.json.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "agentId",
    "focusedRoots",
    "recovery"
  ],
  "properties": {
    "agentId": {
      "type": "string",
      "minLength": 1
    },
    "focusedRoots": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/FocusPair"
      }
    },
    "boardRevision": {
      "type": "string",
      "minLength": 1
    },
    "affectedCases": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Complete authoritative Case ids, not acceptance-root ids; absent for results that do not report a graph write. Never truncate silently."
    },
    "recovery": {
      "$ref": "#/$defs/Recovery"
    },
    "handoff": {
      "$ref": "#/$defs/Handoff"
    }
  },
  "$defs": {
    "ToolName": {
      "type": "string",
      "enum": [
        "OpenCase",
        "ApplyBatch",
        "ApplyAction",
        "CloseCase",
        "QueryBoard",
        "ReadArtifact"
      ]
    },
    "RecoveryState": {
      "type": "string",
      "enum": [
        "none",
        "waiting",
        "result_ready",
        "reconciliation_required"
      ]
    },
    "FocusPair": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "caseId",
        "root"
      ],
      "properties": {
        "caseId": {
          "type": "string",
          "minLength": 1
        },
        "root": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "ClientCapabilities": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "serialRecovery"
      ],
      "properties": {
        "serialRecovery": {
          "const": 1
        }
      },
      "description": "Declared in initialize.capabilities.experimental[\"rulith/v1\"]. A compatibility declaration, never a grant of authority."
    },
    "Recovery": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "state"
      ],
      "properties": {
        "state": {
          "$ref": "#/$defs/RecoveryState"
        },
        "callRef": {
          "type": "string",
          "minLength": 1
        },
        "tool": {
          "$ref": "#/$defs/ToolName"
        },
        "since": {
          "type": "string",
          "minLength": 1
        },
        "retryAfterMs": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "teaching": {
          "type": "string"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "state": {
                "const": "none"
              }
            },
            "required": [
              "state"
            ]
          },
          "then": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "callRef"
                  ]
                },
                {
                  "required": [
                    "tool"
                  ]
                },
                {
                  "required": [
                    "since"
                  ]
                },
                {
                  "required": [
                    "retryAfterMs"
                  ]
                },
                {
                  "required": [
                    "teaching"
                  ]
                }
              ]
            }
          },
          "else": {
            "required": [
              "callRef",
              "tool"
            ]
          }
        }
      ]
    },
    "Handoff": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "callRef",
        "tool",
        "requestExecuted"
      ],
      "properties": {
        "callRef": {
          "type": "string",
          "minLength": 1
        },
        "tool": {
          "$ref": "#/$defs/ToolName"
        },
        "requestExecuted": {
          "const": false
        }
      },
      "description": "The enclosing isError:true tool result contains a previous call result; the current request did not execute. Models receive only its authorized public content, not this metadata."
    }
  }
}

docs/specs/schemas/rulith-artifact-read-.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-artifact-read-v1.schema.json",
  "title": "Immutable generated-result Artifact read contract",
  "description": "Gateway data-plane contract. Production ownership, Source off-machine/storage permission, current disclosure authorization and durable retention are checked separately; reading never creates a Case or changes Board state.",
  "$ref": "#/$defs/ReadArtifact",
  "$defs": {
    "ArtifactRef": {
      "type": "string",
      "pattern": "^art_[a-f0-9]{32}$",
      "description": "Service-minted opaque reference. Knowledge of it does not grant access; never a URL or filesystem path."
    },
    "ReadArtifact": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ref"
      ],
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "offset": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991,
          "default": 0
        },
        "maxBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991,
          "description": "Requested upper bound; omission uses the configured read budget, larger requests are rejected rather than enlarging that budget."
        }
      }
    },
    "ReadArtifactResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ref",
        "mediaType",
        "encoding",
        "data",
        "offset",
        "nextOffset",
        "totalBytes",
        "complete",
        "truncated"
      ],
      "properties": {
        "ref": {
          "$ref": "#/$defs/ArtifactRef"
        },
        "mediaType": {
          "type": "string",
          "minLength": 1
        },
        "encoding": {
          "enum": [
            "utf8",
            "base64"
          ]
        },
        "data": {
          "type": "string"
        },
        "offset": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "nextOffset": {
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            {
              "type": "null"
            }
          ]
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "complete": {
          "type": "boolean"
        },
        "truncated": {
          "type": "boolean"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "complete": {
                "const": true
              }
            },
            "required": [
              "complete"
            ]
          },
          "then": {
            "properties": {
              "nextOffset": {
                "type": "null"
              },
              "truncated": {
                "const": false
              }
            }
          },
          "else": {
            "properties": {
              "nextOffset": {
                "type": "integer",
                "minimum": 0,
                "maximum": 9007199254740991
              },
              "truncated": {
                "const": true
              }
            }
          }
        }
      ],
      "description": "Offsets and totalBytes count the original immutable bytes; utf8 chunks never split a code point, binary data is base64. Completion means this read reached object EOF, not Case completion. The server also checks offset advancement and byte counts."
    },
    "ArtifactPolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "inlineBytes",
        "readBytes",
        "objectBytes",
        "totalBytes",
        "temporaryRetentionMs"
      ],
      "properties": {
        "inlineBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "readBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "objectBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "totalBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "temporaryRetentionMs": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        }
      },
      "description": "Values are supplied by existing deployment/operator configuration. Source permission is independent; quotas do not grant off-machine storage or release retained data."
    }
  }
}

docs/specs/schemas/rulith-board-query-co.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-query-context-v1.schema.json",
  "title": "Protected QueryBoard context",
  "description": "Set by Gateway from authenticated request context, never accepted as Agent tool input. Core validates audience against authenticated principal before reading nodes. Audience enum is checked against QueryBoard.audienceProfiles in operations.json.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "audienceProfile"
  ],
  "properties": {
    "audienceProfile": {
      "type": "string",
      "enum": [
        "agent",
        "operator",
        "internal"
      ]
    },
    "requestedRoots": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Acceptance-root ids, not case ids. Omitted or [] requests no additional root summaries; this never supplies an Agent selector.roots prerequisite."
    }
  },
  "$defs": {
    "AudienceAllowances": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "principals": {
          "type": "object",
          "additionalProperties": {
            "type": "array",
            "uniqueItems": true,
            "items": {
              "type": "string",
              "enum": [
                "agent",
                "operator",
                "internal"
              ]
            }
          }
        },
        "default": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "const": "agent"
          },
          "description": "Absence means the agent base allowance; operator/internal cannot be granted through a default."
        }
      }
    }
  }
}

docs/specs/schemas/rulith-board-v1.schem.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "rulith-board-v1.schema.json",
  "title": "Rulith Board Protocol v1 (rulith-board/1)",
  "description": "Normative artifact promised by protocol-spec section 3. RT-SCHEMA guards keep this Schema, the operation model, documentation, and the Rust advertisement aligned. Every command accepted by protocol conformance fixtures must validate against this Schema. Required fields are the wire-level fields whose absence the authoritative service rejects. Identity is not part of this Schema: principal, roles, and channelId are injected by authenticated transport and never accepted from the request body. The root shape is BoardCommand; responses and events are BoardResult and BoardEvent.",
  "$ref": "#/$defs/BoardCommand",
  "$defs": {
    "BoardCommand": {
      "description": "Command envelope. requestId provides idempotency and expectedRevision provides optimistic concurrency; a mismatch is rejected atomically as stale_revision. The envelope remains open for backward-compatible field additions, while each operation shape remains closed.",
      "type": "object",
      "required": [
        "protocol",
        "boardId",
        "requestId",
        "operation"
      ],
      "additionalProperties": true,
      "properties": {
        "protocol": {
          "const": "rulith-board/1"
        },
        "locale": {
          "type": "string",
          "enum": [
            "en"
          ],
          "description": "Presentation language for this response. It affects teaching and presentation only and never enters closure, revision, or idempotency identity. Omitted means en. Any other value is rejected with bad_command; GetProtocolManifest.locales advertises the supported set."
        },
        "boardId": {
          "type": "string",
          "minLength": 1
        },
        "requestId": {
          "type": "string",
          "minLength": 1
        },
        "expectedRevision": {
          "type": "string"
        },
        "case": {
          "type": "object",
          "required": [
            "id"
          ],
          "additionalProperties": false,
          "description": "Case Context. A command binds to at most one Case; expectedRevision is the Case-local cN revision and is unaffected by writes to other Cases.",
          "properties": {
            "id": {
              "type": "string",
              "minLength": 1
            },
            "expectedRevision": {
              "type": "string",
              "pattern": "^c[0-9]+$"
            }
          }
        },
        "operation": {
          "$ref": "#/$defs/BoardOperation"
        }
      }
    },
    "BoardOperation": {
      "description": "v1 操作面(名单与 TS BoardOperation 联合类型逐项相等——数字不手写,RT-SCHEMA-1 执法)。",
      "oneOf": [
        {
          "$ref": "#/$defs/GetProjection"
        },
        {
          "$ref": "#/$defs/GetChanges"
        },
        {
          "$ref": "#/$defs/GetCompletion"
        },
        {
          "$ref": "#/$defs/QueryBoard"
        },
        {
          "$ref": "#/$defs/GetBoardManifest"
        },
        {
          "$ref": "#/$defs/EvaluateCandidateShadow"
        },
        {
          "$ref": "#/$defs/ReadBillingOutbox"
        },
        {
          "$ref": "#/$defs/AcknowledgeBillingOutbox"
        },
        {
          "$ref": "#/$defs/RunDischarge"
        },
        {
          "$ref": "#/$defs/ApplyBatch"
        },
        {
          "$ref": "#/$defs/Explain"
        },
        {
          "$ref": "#/$defs/IngestObservation"
        },
        {
          "$ref": "#/$defs/RegisterPack"
        },
        {
          "$ref": "#/$defs/RemovePack"
        },
        {
          "$ref": "#/$defs/CreateBoard"
        },
        {
          "$ref": "#/$defs/OpenCase"
        },
        {
          "$ref": "#/$defs/PauseCase"
        },
        {
          "$ref": "#/$defs/ResumeCase"
        },
        {
          "$ref": "#/$defs/MaintainBoardShared"
        },
        {
          "$ref": "#/$defs/SetBoardSuspended"
        },
        {
          "$ref": "#/$defs/GrantRole"
        },
        {
          "$ref": "#/$defs/RevokeRole"
        },
        {
          "$ref": "#/$defs/GetProtocolManifest"
        },
        {
          "$ref": "#/$defs/GetHealth"
        },
        {
          "$ref": "#/$defs/CloseCase"
        },
        {
          "$ref": "#/$defs/GrantClearance"
        },
        {
          "$ref": "#/$defs/DefineRole"
        },
        {
          "$ref": "#/$defs/ExecuteApprovedProposal"
        },
        {
          "$ref": "#/$defs/ListWork"
        },
        {
          "$ref": "#/$defs/ClaimWork"
        },
        {
          "$ref": "#/$defs/ApplyAction"
        },
        {
          "$ref": "#/$defs/ReportWork"
        },
        {
          "$ref": "#/$defs/SealBoard"
        }
      ]
    },
    "SealBoard": {
      "type": "object",
      "required": [
        "kind"
      ],
      "additionalProperties": false,
      "description": "Seal the Agent Board as a terminal governance action. completed is rejected with errorCode=case_pending while any Case or trusted obligation remains open. cancelled, failed, and abandoned are explicit void dispositions and require a non-empty reason. Sealing is host-governed, idempotent, and does not make archived node state disappear from audit reads.",
      "properties": {
        "kind": {
          "const": "SealBoard"
        },
        "reason": {
          "type": "string"
        },
        "disposition": {
          "enum": [
            "completed",
            "cancelled",
            "failed",
            "abandoned"
          ]
        },
        "successor": {
          "type": "string"
        }
      }
    },
    "GetProjection": {
      "type": "object",
      "required": [
        "kind"
      ],
      "additionalProperties": false,
      "properties": {
        "kind": {
          "const": "GetProjection"
        },
        "format": {
          "enum": [
            "text",
            "json"
          ],
          "description": "缺省 text(MCP/CLI 渲染面);json=整个 LogicContext(规范结果)。"
        },
        "attention": {
          "type": "object",
          "additionalProperties": false,
          "description": "有损聚焦轴(§6.5.1): 至少给 focus 或 budget 一维(空对象=教学拒);与 include:'taskStatus' 互斥(裁决读必须在无损全板真相上算)。响应带 attention:{lossy,dropped:{facts,findings},focus?} 自述丢弃量。地板(leaf_gap/delivery_gap/bridge_needs_source/bridge_no_positive_evidence/breach_gap_in/slot_conflict)**豁免预算**: 先摘出恒留、预算只管其余,地板超预算时如实撑破并报 floorKept(VIEW-01 是不变量,不是优先级——真板实跑证伪过 pin-only 版)。",
          "properties": {
            "focus": {
              "type": "string",
              "description": "焦点根 id: 压缩非焦点树(单根板恒等零损失)。"
            },
            "budget": {
              "type": "object",
              "additionalProperties": false,
              "description": "条数上限。整数打分排序取前 N 后复原板序(disputed+100/种子谓词+10/种子实参每个+3/derived+1;同分板序后者优先)——全整数无浮点,故 TS/Rust 可逐字节对齐。",
              "properties": {
                "facts": {
                  "type": "number"
                },
                "findings": {
                  "type": "number"
                }
              }
            },
            "pin": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "额外必留谓词(地板之外)。"
            }
          }
        }
      }
    },
    "GetChanges": {
      "type": "object",
      "required": [
        "kind"
      ],
      "additionalProperties": false,
      "properties": {
        "kind": {
          "const": "GetChanges"
        },
        "sinceRevision": {
          "type": "string",
          "description": "缺省=全量;超窗(delta 环 256 段)返回 resync 教学。"
        }
      }
    },
    "GetCompletion": {
      "type": "object",
      "required": [
        "kind",
        "root"
      ],
      "additionalProperties": false,
      "properties": {
        "kind": {
          "const": "GetCompletion"
        },
        "root": {
          "type": "string"
        }
      }
    },
    "QueryBoard": {
      "type": "object",
      "required": [
        "kind"
      ],
      "additionalProperties": false,
      "description": "可筛选窄读(protocol-spec §6 v1 切片): selector 与集(AND);limit 截断如实报(total/truncated);atRevision 只服务当前修订(不合=stale_revision,绝不静默读现值冒充历史);include 含 taskStatus 时多根裁决与节点同一读快照同一 revision(需 selector.roots);include 含 cases 时 Case 目录与其余肢体同一读快照。attention=有损聚焦轴(§6.5.1,已点亮);cursor/trustTiers/directEvidence 仍是 v2 面,携带即教学拒(不在本 Schema)。",
      "properties": {
        "kind": {
          "const": "QueryBoard"
        },
        "selector": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "nodeIds": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "predicates": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "只作用于 fact/finding;在场即结构性不含 goal(目标无谓词)。"
            },
            "nodeKinds": {
              "type": "array",
              "items": {
                "enum": [
                  "fact",
                  "finding",
                  "goal"
                ]
              }
            },
            "roots": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "include=taskStatus 的裁决根集;include=cases 时是目录的请求根集(精确匹配、重复归一;空数组=教学拒,不猜「全都要」)。"
            }
          }
        },
        "include": {
          "type": "array",
          "items": {
            "enum": [
              "nodes",
              "taskStatus",
              "gaps",
              "receipts",
              "cases"
            ]
          },
          "description": "缺省 [\"nodes\"];gaps=advisory 缺口(bridge_needs_source/leaf_gap/delivery_gap——不可领取,工人队列在工人面),与节点/taskStatus 同一读快照(金样 46)。receipts=canonical 回执一族(rulith-receipt/1): retention=durable 的结案回执(CloseCase/SealBoard,永不淘汰)＋ retention=hot 的 pending 处理回执(share_*／update_* 四态,按 hotReceiptCap 有损淘汰)。回执不是板上的事实——不进闭包、不进默认投影,点了才给。cases=**有界 Case 目录**(交互细则 §3.2 首行): 每条恰 caseId／root／status 三键,status ∈ running｜paused｜closed;板级读,无需先选 Case;显式点亮才给(缺省不含 cases——安全缺省属 Profile 采用批)。selector.roots 过滤时逐根给出条目或 unavailableRoots(不存在／删除／不可见合并,零理由);truncated 与 unavailableRoots 各自自述,被 limit 砍掉的根不算 unavailable。目录不带节点、回执、digest、epoch、revision 或物理 id;与目录同请求但无 nodes 肢体的节点面输入(nodeIds／predicates／nodeKinds／attention)一律教学拒。**畸形形与型也一律可见拒**(bad_command,零 Board 数据、零写入): 判据落在原始 wire 上、先于任何归一,故 selector 非对象、列表非串数组、limit 非法值域都不会被静默丢成「没给」或强转成缺省——两者分别把请求答宽和答窄,且回执里没有一个字与之矛盾。严值域见下方 allOf 条件分支。"
        },
        "atRevision": {
          "type": "string"
        },
        "limit": {
          "type": "number",
          "description": "缺省 500;截断序 facts→findings→goals(板序)。**目录读(include 含 cases)另有更严的值域**,见下方 allOf 的条件分支;旧肢体的宽松强制留到 Profile 协调采用批一次改齐,本 Schema 不预先收紧它。"
        },
        "attention": {
          "type": "object",
          "additionalProperties": false,
