              "enum": [
                "satisfied",
                "not_satisfied",
                "error"
              ],
              "description": "Explicit three-state verification result. satisfied: the verification ran and the condition holds. not_satisfied: the verification ran normally and the condition does not hold under the current world state — a terminal business answer that spends no failure-retry budget. error: executor, channel, or backend failure — retry backoff applies. A verification report that omits outcome is rejected with bad_command and teaching that names all three values."
            },
            "tier": {
              "$ref": "#/$defs/PremiseTier"
            },
            "evidenceRefs": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "reason": {
              "type": "string"
            },
            "facts": {
              "type": "array",
              "items": {
                "type": "object",
                "required": [
                  "predicate",
                  "args"
                ],
                "additionalProperties": false,
                "properties": {
                  "predicate": {
                    "type": "string"
                  },
                  "args": {
                    "type": "object",
                    "additionalProperties": {
                      "type": [
                        "string",
                        "number",
                        "boolean"
                      ]
                    }
                  }
                }
              }
            }
          }
        },
        {
          "type": "object",
          "required": [
            "kind",
            "workType",
            "id",
            "ok",
            "execution"
          ],
          "additionalProperties": false,
          "properties": {
            "kind": {
              "const": "ReportWork"
            },
            "workType": {
              "const": "action"
            },
            "id": {
              "type": "string"
            },
            "ok": {
              "type": "boolean"
            },
            "result": {
              "type": "string"
            },
            "reason": {
              "type": "string"
            },
            "execution": {
              "$ref": "#/$defs/ExecutionIdentity"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "kind",
            "workType",
            "tool",
            "norm",
            "verdict",
            "citedClause",
            "reason"
          ],
          "additionalProperties": false,
          "properties": {
            "kind": {
              "const": "ReportWork"
            },
            "workType": {
              "const": "review"
            },
            "tool": {
              "type": "string"
            },
            "norm": {
              "type": "string"
            },
            "verdict": {
              "enum": [
                "allow",
                "block",
                "not_applicable",
                "uncertain"
              ]
            },
            "citedClause": {
              "type": "string"
            },
            "feature": {
              "type": "string"
            },
            "reason": {
              "type": "string"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "kind",
            "workType",
            "material",
            "facts"
          ],
          "additionalProperties": false,
          "description": "取材回报(spec §6 取材那一环): 工人查回来的材料落板。通道只能就它绑了的词作证——档位来自通道,不来自内容。",
          "properties": {
            "kind": {
              "const": "ReportWork"
            },
            "workType": {
              "const": "evidence"
            },
            "material": {
              "type": "string",
              "description": "这次查的是哪样材料"
            },
            "facts": {
              "type": "array",
              "items": {
                "type": "object",
                "required": [
                  "predicate",
                  "args"
                ],
                "properties": {
                  "predicate": {
                    "type": "string"
                  },
                  "args": {
                    "type": "object",
                    "additionalProperties": {
                      "type": [
                        "string",
                        "number",
                        "boolean"
                      ]
                    }
                  }
                },
                "additionalProperties": false
              }
            }
          }
        }
      ]
    },
    "AgentOpenCase": {
      "type": "object",
      "description": "OpenCase as the model sends it: business fields only. No kind (the tool name carries it), no identity, no envelope metadata.",
      "oneOf": [
        {
          "type": "object",
          "required": [
            "caseType"
          ],
          "additionalProperties": false,
          "properties": {
            "caseType": {
              "type": "string",
              "pattern": "^[a-z][a-z0-9_-]{1,63}$"
            },
            "businessKey": {
              "type": "object"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "caseId"
          ],
          "additionalProperties": false,
          "properties": {
            "caseId": {
              "type": "string",
              "minLength": 1
            }
          }
        }
      ]
    },
    "AgentApplyBatch": {
      "type": "object",
      "required": [
        "operations"
      ],
      "additionalProperties": false,
      "description": "Structured writes onto the shared graph. The inner operation names come from the Board batch contract; this shape references it rather than restating a second closed list.",
      "properties": {
        "operations": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/WorkingMemoryOperation"
          }
        }
      }
    },
    "AgentApplyAction": {
      "type": "object",
      "required": [
        "action"
      ],
      "additionalProperties": false,
      "description": "Invoke an Action the Board View currently shows as available. A Source-bound Action takes its logical source name inside args — never a Connection, credential, URL or local entry point.",
      "properties": {
        "action": {
          "type": "string",
          "minLength": 1
        },
        "args": {
          "type": "object"
        },
        "target": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "AgentCloseCase": {
      "type": "object",
      "required": [
        "root"
      ],
      "additionalProperties": false,
      "description": "Request a terminal state for one named acceptance boundary. Closing one root never closes another.",
      "properties": {
        "root": {
          "type": "string",
          "minLength": 1
        },
        "disposition": {
          "$ref": "#/$defs/CloseCase/properties/disposition"
        },
        "reason": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "AgentQueryBoard": {
      "type": "object",
      "additionalProperties": false,
      "description": "Bounded read of the Board View. queryContext is deliberately absent: the audience Profile is protected envelope metadata the Gateway derives from the authenticated request, and a model-facing shape that carried it would make the disclosure boundary something the caller sets. Omitting include returns the bounded Case directory; nodes, gaps and taskStatus each require an explicit selector.roots.",
      "properties": {
        "include": {
          "type": "array",
          "items": {
            "enum": [
              "cases",
              "nodes",
              "gaps",
              "taskStatus"
            ]
          }
        },
        "selector": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "roots": {
              "allOf": [
                {
                  "$ref": "#/$defs/QueryBoard/allOf/0/then/properties/selector/properties/roots"
                },
                {
                  "minItems": 1,
                  "items": {
                    "minLength": 1
                  }
                }
              ]
            }
          }
        },
        "limit": {
          "$ref": "#/$defs/QueryBoard/allOf/0/then/properties/limit"
        }
      },
      "allOf": [
        {
          "if": {
            "required": [
              "include"
            ],
            "properties": {
              "include": {
                "contains": {
                  "enum": [
                    "nodes",
                    "gaps",
                    "taskStatus"
                  ]
                }
              }
            }
          },
          "then": {
            "required": [
              "selector"
            ],
            "properties": {
              "selector": {
                "required": [
                  "roots"
                ]
              }
            }
          }
        }
      ]
    },
    "OperatorQueryBoard": {
      "type": "object",
      "additionalProperties": false,
      "description": "Console audit read, filtered by the operator Authority. Broader selectors than the Agent Profile, still bounded, and still refused without a Profile — no audience falls back to a whole-graph default.",
      "properties": {
        "include": {
          "type": "array",
          "items": {
            "enum": [
              "cases",
              "nodes",
              "gaps",
              "taskStatus",
              "receipts"
            ]
          }
        },
        "selector": {
          "$ref": "#/$defs/BroadReadSelector"
        },
        "atRevision": {
          "type": "string",
          "minLength": 1
        },
        "limit": {
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "InternalQueryBoard": {
      "type": "object",
      "additionalProperties": false,
      "description": "Authenticated service-to-service read. Broadest selectors; still Authority/disclosure filtered and still Profile-gated.",
      "properties": {
        "include": {
          "type": "array",
          "items": {
            "enum": [
              "cases",
              "nodes",
              "gaps",
              "taskStatus",
              "receipts"
            ]
          }
        },
        "selector": {
          "$ref": "#/$defs/BroadReadSelector"
        },
        "atRevision": {
          "type": "string",
          "minLength": 1
        },
        "limit": {
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "BroadReadSelector": {
      "type": "object",
      "additionalProperties": false,
      "description": "The selector surface the operator and internal Profiles share. It is one definition rather than two copies: two copies of a disclosure surface drift, and the wider of the two wins by accident.",
      "properties": {
        "roots": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "caseIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "nodeIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "predicates": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "nodeKinds": {
          "type": "array",
          "items": {
            "enum": [
              "fact",
              "finding",
              "goal"
            ]
          }
        }
      }
    }
  }
}

protocol/mcp-surface.json.content:
{
  "schema": "rulith-mcp-surface/v1",
  "protocolVersion": "2025-11-25",
  "description": "PSC 0.2.4 adoption contract for public Agent tool membership and dispatch. Its existence does not attest that a running server has adopted it. schemaRef values identify files from the Core repository root; vendors verify a source-path-to-bytes map against the named Git commit and resolve it without network access. Adopting Gateways serve each inputSchema directly from the verified rulith-mcp-contract-bundle/v1 tools entry, including its generated definition names and explicit dialect. Object key order and JSON whitespace are immaterial; independently regenerated schema shapes are not the delivered contract.",
  "metadata": {
    "namespace": "rulith/v1",
    "schemaRef": "docs/specs/schemas/rulith-agent-mcp-meta-v1.schema.json"
