protocol/operations.json.content:
{
  "format": "rulith-operations/1",
  "note": "Single source of truth for the operation surface. gen:operations emits op_registry_g.rs for the server and op_shape_g.rs for the protocol. Exhaustive Operation matches such as is_write_operation and case_context_class remain handwritten because compiler exhaustiveness is stronger than generated string tables; op_registry_conform.rs checks every sample against this registry. Array order is the byte-stable GetProtocolManifest advertisement order.",
  "fieldNote": "write identifies journaled write operations; caseContext is required, optional, or boardOnly; selfDescribing means a BoardShared read without a Case identifies its returned context; expiredBypass allows an expired Case to finish terminalization or reads; required entries are [field, s|b|a|p], where p checks presence only; manifest tags membership in default, caseLevel, or boardShared surfaces; sample is the minimal valid wire shape used by conformance tests.",
  "operations": [
    {
      "kind": "GetProjection",
      "write": false,
      "caseContext": "optional",
      "selfDescribing": true,
      "expiredBypass": true,
      "required": [],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "GetProjection"
      }
    },
    {
      "kind": "GetChanges",
      "write": false,
      "caseContext": "optional",
      "selfDescribing": true,
      "expiredBypass": true,
      "required": [],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "GetChanges"
      }
    },
    {
      "kind": "GetCompletion",
      "write": false,
      "caseContext": "optional",
      "selfDescribing": true,
      "expiredBypass": true,
      "required": [
        [
          "root",
          "s"
        ]
      ],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "GetCompletion",
        "root": "R"
      }
    },
    {
      "kind": "QueryBoard",
      "audienceProfiles": {
        "agent": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/AgentQueryBoard",
        "operator": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/OperatorQueryBoard",
        "internal": "docs/specs/schemas/rulith-board-v1.schema.json#/$defs/InternalQueryBoard"
      },
      "write": false,
      "caseContext": "optional",
      "selfDescribing": true,
      "expiredBypass": true,
      "required": [],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "QueryBoard"
      },
      "note": "include accepts nodes, taskStatus, gaps, receipts, and cases. cases is the bounded Case directory required by the approved contract's Agent interaction annex: one row per Case carrying only the business Case id, its acceptance root, and its lifecycle status, readable at Board level so a caller need not name a Case to discover one. It is explicit opt-in in this checkpoint; the missing-include default is still nodes, and the audience Profile default belongs to the coordinated Profile adoption. The agentRead marking and the Profile schema references the annex also requires are not projected here yet."
    },
    {
      "kind": "GetBoardManifest",
      "write": false,
      "caseContext": "optional",
      "selfDescribing": false,
      "expiredBypass": true,
      "required": [],
      "manifest": [
        "default",
        "boardShared",
        "caseLevel"
      ],
      "sample": {
        "kind": "GetBoardManifest"
      },
      "note": "Not marked selfDescribing because works[], work{}, and lifecycle already state the scope explicitly."
    },
    {
      "kind": "EvaluateCandidateShadow",
      "write": false,
      "caseContext": "required",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [
        ["candidateId", "s"],
        ["candidateArtifactDigest", "s"],
        ["replayReportDigest", "s"],
        ["expectedBaseProgramDigest", "s"],
        ["baseReleaseDigests", "a"],
        ["targetCapability", "p"],
        ["programDigest", "s"],
        ["program", "p"]
      ],
      "manifest": [],
      "sample": {
        "kind": "EvaluateCandidateShadow",
        "candidateId": "capcand_0123456789abcdef0123456789abcdef",
        "candidateArtifactDigest": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        "replayReportDigest": "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
        "expectedBaseProgramDigest": "sha256:cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
        "baseReleaseDigests": ["sha256:dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd"],
        "targetCapability": {"ownerPrincipal": "tenant", "id": "orders"},
        "programDigest": "sha256:eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
        "program": {
          "format": "rulith-domain-program",
          "meta": {"name": "orders", "version": 1, "deps": [], "provides": ["orders"]},
          "axioms": [],
          "empirical": [],
          "theorems": [],
          "vocab": [],
          "actions": []
        }
      },
      "note": "Control-plane-only, effect-free evaluation on a detached Case frontier. It is intentionally absent from default, BoardShared, Case-level, Agent, Worker, and MCP advertisements."
    },
    {
      "kind": "ReadBillingOutbox",
      "write": false,
      "caseContext": "boardOnly",
      "selfDescribing": false,
      "expiredBypass": true,
      "required": [],
      "manifest": [],
      "sample": {
        "kind": "ReadBillingOutbox",
        "afterSequence": 0,
        "limit": 100,
        "includeAcknowledged": false
      },
      "note": "Authenticated governance/billing control-plane read of the immutable terminal denominator ledger. It is intentionally absent from Agent, Worker, MCP, default, BoardShared, and Case-level advertisements."
    },
    {
      "kind": "AcknowledgeBillingOutbox",
      "write": true,
      "caseContext": "boardOnly",
      "selfDescribing": false,
      "expiredBypass": true,
      "required": [
        ["outboxId", "s"],
        ["terminalReceiptDigest", "s"],
        ["usageDigest", "s"]
      ],
      "manifest": [],
      "sample": {
        "kind": "AcknowledgeBillingOutbox",
        "outboxId": "bout_0123456789abcdef0123456789abcdef",
        "terminalReceiptDigest": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        "usageDigest": "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
      },
      "note": "Authenticated governance/billing control-plane append-only acknowledgement. It binds the immutable item by outbox id, terminal receipt digest, and usage digest and never deletes the item."
    },
    {
      "kind": "RunDischarge",
      "write": true,
      "caseContext": "required",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [],
      "manifest": [
        "caseLevel"
      ],
      "sample": {
        "kind": "RunDischarge"
      },
      "note": "The advertised surface also applies the runtime can_discharge predicate; this static table defines membership only."
    },
    {
      "kind": "ApplyBatch",
      "agentVerb": true,
      "write": true,
      "caseContext": "required",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [
        [
          "operations",
          "a"
        ]
      ],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "ApplyBatch",
        "operations": []
      }
    },
    {
      "kind": "CloseCase",
      "agentVerb": true,
      "write": true,
      "caseContext": "required",
      "selfDescribing": false,
      "expiredBypass": true,
      "required": [
        [
          "root",
          "s"
        ]
      ],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "CloseCase",
        "root": "R"
      }
    },
    {
      "kind": "Explain",
      "write": false,
      "caseContext": "optional",
      "selfDescribing": true,
      "expiredBypass": true,
      "required": [
        [
          "nodeId",
          "s"
        ]
      ],
      "manifest": [
        "default",
        "caseLevel"
      ],
      "sample": {
        "kind": "Explain",
        "nodeId": "N"
      }
    },
    {
      "kind": "IngestObservation",
      "write": true,
      "caseContext": "required",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [
        [
          "facts",
          "a"
        ]
      ],
      "manifest": [
        "caseLevel"
      ],
      "sample": {
        "kind": "IngestObservation",
        "facts": [
          {
            "predicate": "probe",
            "args": {}
          }
        ]
      },
      "note": "The advertised surface additionally requires a channel identity and an on-board ingest target binding."
    },
    {
      "kind": "RegisterPack",
      "write": true,
      "caseContext": "boardOnly",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [
        [
          "packType",
          "s"
        ],
        [
          "pack",
          "p"
        ]
      ],
      "manifest": [
        "boardShared"
      ],
      "sample": {
        "kind": "RegisterPack",
        "packType": "domain",
        "pack": {}
      },
      "note": "The advertised surface additionally requires an unlocked board and may_legislate authorization."
    },
    {
      "kind": "RemovePack",
      "write": true,
      "caseContext": "boardOnly",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [
        ["packType", "s"],
        ["name", "s"],
        ["expectedDigest", "s"]
      ],
      "manifest": ["boardShared"],
      "sample": {
        "kind": "RemovePack",
        "packType": "domain",
        "name": "verified-calculation",
        "expectedDigest": "sha256:current"
      },
      "note": "Governed CAS-pinned removal of one effective package. It queues behind open Cases and is advertised only when the caller may legislate and the law lock is open."
    },
    {
      "kind": "CreateBoard",
      "write": true,
      "caseContext": "boardOnly",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [],
      "manifest": [],
      "sample": {
        "kind": "CreateBoard",
        "title": "t"
      },
      "note": "Never appears in a board Manifest because the board does not exist before this operation."
    },
    {
      "kind": "OpenCase",
      "agentVerb": true,
      "write": true,
      "caseContext": "boardOnly",
      "selfDescribing": false,
      "expiredBypass": false,
      "required": [
        [
          "root",
          "s"
        ],
        [
          "caseId",
          "s"
        ],
        [
          "expectedBoardSharedEpoch",
          "n"
        ],
        [
          "capabilityReleaseDigest",
          "s"
        ],
        [
          "caseType",
          "s"
        ],
        [
          "caseContractDigest",
          "s"
        ],
        [
          "businessKeyDigest",
          "p"
        ],
        [
          "commercialTermsDigest",
          "s"
        ],
        [
          "maxExplorationBps",
          "n"
        ]
      ],
      "manifest": [
        "boardShared"
      ],
      "sample": {
        "kind": "OpenCase",
        "root": "R",
        "caseId": "case-1",
        "expectedBoardSharedEpoch": 0,
        "capabilityReleaseDigest": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        "caseType": "exploration",
        "caseContractDigest": "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
        "businessKeyDigest": null,
        "commercialTermsDigest": "sha256:cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
        "maxExplorationBps": 0
      },
      "note": "OpenCase hard-requires expectedBoardSharedEpoch from the authoritative Board Manifest; admission rejects stale composition before creating a Case or freezing commercial pins. The advertised surface also applies runtime Case admission checks."
    },
    {
      "kind": "PauseCase",
      "write": true,
